<?php
require_once __DIR__.'/../../includes/bootstrap.php'; require_role('admin'); csrf_check();
$name=trim($_POST['nama_kegiatan']??''); $number=trim($_POST['nomor_kegiatan']??''); $username=trim($_POST['username']??''); $password=(string)($_POST['password']??''); $start=$_POST['tanggal_mulai']??''; $end=$_POST['tanggal_selesai']??''; $status=$_POST['status']??'aktif'; $target=$_POST['tujuan_akhir']??''; $desc=trim($_POST['deskripsi']??'');
if (!$name||!$number||!$username||strlen($password)<8||!$start||!$end||$end<$start||!in_array($status,['aktif','nonaktif'],true)||!in_array($target,['lpd','kwitansi','keduanya'],true)) { flash('danger','Periksa kembali isian kegiatan. Pastikan periode valid dan password minimal 8 karakter.'); redirect('/admin/kegiatan/create.php'); }
try { $pdo->beginTransaction(); $q=$pdo->prepare('INSERT INTO kegiatan (created_by,nama_kegiatan,nomor_kegiatan,tanggal_mulai,tanggal_selesai,status,deskripsi,tujuan_akhir) VALUES (?,?,?,?,?,?,?,?)'); $q->execute([current_user()['id_user'],$name,$number,$start,$end,$status,$desc?:null,$target]); $id=(int)$pdo->lastInsertId(); $u=$pdo->prepare("INSERT INTO users (id_kegiatan,username,password,role_user) VALUES (?,?,?,'petugas')"); $u->execute([$id,$username,password_hash($password,PASSWORD_DEFAULT)]); $pdo->commit(); flash('success','Kegiatan dan akun petugas berhasil dibuat.'); redirect('/admin/kegiatan/detail.php?id='.$id); } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); flash('danger',$e instanceof PDOException && str_contains($e->getMessage(),'uq_users_username')?'Username sudah digunakan. Gunakan username lain.':'Kegiatan gagal disimpan. Periksa data dan koneksi database.'); redirect('/admin/kegiatan/create.php'); }
